function attachmentExt(name){return String(name||'').split('.').pop().toLowerCase()}
async function loadPreviewLibrary(url,check){if(check())return;const script=document.createElement('script');script.src=url;script.async=true;await new Promise((ok,fail)=>{script.onload=()=>check()?ok():fail(Error('Bibliothèque chargée mais indisponible'));script.onerror=()=>fail(Error('Bibliothèque de prévisualisation indisponible'));document.head.appendChild(script)})}
